### 2. RoomConfig.cs
Located at `D:\dai_ma\Unity\WenJianGamejam_2026\Assets\Scripts\Map\Config\RoomConfig.cs`. Full content:

```csharp
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间配置 – 定义某一类房间的通用参数 + 多个可选预制体变体
/// </summary>
[CreateAssetMenu(fileName = "RoomConfig", menuName = "Map/Room Config")]
public class RoomConfig : ScriptableObject
{
    [Header("基础信息")]
    [Tooltip("房间类型")]
    public RoomType roomType;

    [Tooltip("可选房间预制体列表 (生成时随机选取一个)")]
    public GameObject[] roomPrefabs;

    [Tooltip("难度等级 (影响怪物属性缩放宽等)")]
    public int difficultyLevel = 1;

    [Header("连接点 – 该房间有哪些方向的门")]
    public bool hasTopDoor;
    public bool hasBottomDoor;
    public bool hasLeftDoor;
    public bool hasRightDoor;

    [Header("房间尺寸 (世界单位，用于摄像机边界和布局计算)")]
    public Vector2 roomSize = new Vector2(20f, 12f);

    [Header("门在房间内的本地坐标偏移")]
    public Vector2 topDoorOffset = new Vector2(0f, 6.5f);
    public Vector2 bottomDoorOffset = new Vector2(0f, -6.5f);
    public Vector2 leftDoorOffset = new Vector2(-10.5f, 0f);
    public Vector2 rightDoorOffset = new Vector2(10.5f, 0f);

    [Header("怪物生成")]
    [Tooltip("可选的怪物池")]
    public List<EnemySpawnEntry> enemyPool = new();

    [Tooltip("最少生成怪物数")]
    public int minEnemies = 1;

    [Tooltip("最多生成怪物数")]
    public int maxEnemies = 3;

    [Header("道具生成")]
    [Tooltip("可选道具池")]
    public List<GameObject> itemPool = new();

    [Tooltip("最少道具数")]
    public int minItems = 0;

    [Tooltip("最多道具数")]
    public int maxItems = 2;

    [Header("隐藏墙")]
    [Tooltip("隐藏墙血量 (需要攻击次数；0=普通门)")]
    public int hiddenWallHP = 0;

    /// <summary>获取指定方向门的本地坐标偏移</summary>
    public Vector2 GetDoorOffset(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => topDoorOffset,
            DoorDirection.Bottom => bottomDoorOffset,
            DoorDirection.Left => leftDoorOffset,
            DoorDirection.Right => rightDoorOffset,
            _ => Vector2.zero
        };
    }

    /// <summary>检查是否有指定方向的门</summary>
    public bool HasDoor(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => hasTopDoor,
            DoorDirection.Bottom => hasBottomDoor,
            DoorDirection.Left => hasLeftDoor,
            DoorDirection.Right => hasRightDoor,
            _ => false
        };
    }

    /// <summary>获取门的相反方向</summary>
    public static DoorDirection OppositeDir(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => DoorDirection.Bottom,
            DoorDirection.Bottom => DoorDirection.Top,
            DoorDirection.Left => DoorDirection.Right,
            DoorDirection.Right => DoorDirection.Left,
            _ => DoorDirection.Top
        };
    }

    /// <summary>从预制体池中随机选取一个。池为空时返回 null。</summary>
    public GameObject GetRandomPrefab()
    {
        if (roomPrefabs == null || roomPrefabs.Length == 0) return null;
        return roomPrefabs[Random.Range(0, roomPrefabs.Length)];
    }
}
```

### 3. ItemData.cs
Located at `D:\dai_ma\Unity\WenJianGamejam_2026\Assets\Scripts\Item\Core\ItemData.cs`. Full content:

```csharp
using UnityEngine;

/// <summary>
/// 道具数据资产（ScriptableObject）– 定义一种道具的所有静态属性。
/// 右键 -> Create -> Game -> Item Data 创建。
/// 参考：以撒的结合道具 / 崩坏星穹铁道奇物 / 明日方舟藏品。
/// </summary>
[CreateAssetMenu(fileName = "NewItem", menuName = "Game/Item Data")]
public class ItemData : ScriptableObject
{
    [Header("基本信息")]
    [Tooltip("唯一标识，如 'blood_of_martyr'")]
    public string itemId;              // 唯一标识
    public string itemName;            // 显示名称
    [TextArea] public string description;
    public Sprite icon;
    [Tooltip("品质: Common/Uncommon/Rare/Legendary")]
    public ItemQuality quality;        // 品质

    [Header("效果（策略模式）")]
    [Tooltip("拖入具体效果资产: ItemEffectBase 子类")]
    public ItemEffectBase effect;      // 道具效果策略

    [Header("商店")]
    [Tooltip("在商店购买时的 ATP 价格；0 = 不可购买")]
    [Min(0)] public int price = 10;

    [Header("获取限制")]
    [Tooltip("可获取的数量上限。0 = 无限制，>0 = 最多持有该数量")]
    [Min(0)] public int maxCount;     // 数量上限
}
```

### 4. "RecordRoomVisited" / "RecordRoomCleared" calling code

Found in `Map/Runtime/RoomManager.cs`. Four matches total, but only two files are involved:

**Location A — RoomManager.cs around L70-79 (first-room entry):**
```csharp
if (_isFirstEnter)
{
    _isFirstEnter = false;

    // 统计：首次进入房间
    GameStatistics.Instance?.RecordRoomVisited();

    SpawnEnemies();
    Debug.Log($"[RoomManager] Room{roomRoot.roomId} spawned enemies, _aliveEnemies.Count={_aliveEnemies.Count}");

    if (_aliveEnemies.Count > 0)
    ...
```

**Location B — RoomManager.cs around L221-230 (room cleared):**
```csharp
// Boss/Exit 房生成下一层出口
TrySpawnNextLevelExit();

Debug.Log($"Room {roomRoot.roomId}: 已清空!");

// 统计：清空房间
GameStatistics.Instance?.RecordRoomCleared();

OnRoomCleared?.Invoke();
```

**Definitions in `SystemUI/GameStatistics.cs` (L141-142):**
```csharp
public void RecordRoomVisited() => RoomsVisited++;
public void RecordRoomCleared() => RoomsCleared++;
```

The definitions reside in `GameStatistics.cs`; the only call sites are in `RoomManager.cs`. `RecordRoomVisited()` is called once on the first room entry (guarded by `_isFirstEnter`), and `RecordRoomCleared()` is called when a room is fully cleared, right before `OnRoomCleared?.Invoke()`.

## Caveat
The `read_file` tool reported all three files as "File unchanged since last read" (they were read earlier in this session), so I retrieved content via `Get-Content` in PowerShell. The raw shell output showed the Chinese comments as mojibake due to console encoding; I've reconstructed the readable comment text based on the field names and context. The actual C# code (identifiers, types, attributes, values) is verified exact.

